#include "coagentics/experiment/MarketScientist.hpp"
#include <iostream>
#include <iomanip>
using namespace coagentics;
static const char* disposition(experiment::QuoteDisposition d){using Q=experiment::QuoteDisposition;switch(d){case Q::exhausted:return "exhausted";case Q::no_legal_quote:return "no_legal_quote";case Q::rejected_standing:return "rejected_standing";case Q::accepted:return "accepted";case Q::executed:return "executed";}return "unknown";}
static void outcome(const experiment::MarketOutcome &o){std::cout<<"{\"efficiency\":"<<o.efficiency<<",\"surplus\":"<<o.surplus<<",\"trades\":"<<o.trades<<",\"mean_transaction_price\":"<<o.mean_transaction_price<<",\"target_quotes\":"<<o.target_quotes<<"}";}
static void traces(const std::vector<experiment::DecisionTrace>&v){std::cout<<"[";for(size_t i=0;i<v.size();++i){const auto&t=v[i];if(i)std::cout<<",";std::cout<<"{\"event\":"<<t.event<<",\"actor\":"<<t.actor<<",\"buyer\":"<<(t.buyer?"true":"false")<<",\"unit\":"<<t.marginal_unit<<",\"private_limit\":"<<t.private_limit<<",\"standing_bid\":"<<t.standing_bid<<",\"standing_ask\":"<<t.standing_ask<<",\"news\":"<<t.news_visible<<",\"peer\":"<<t.peer_visible<<",\"attempted\":"<<(t.attempted?"true":"false")<<",\"desired_price\":"<<t.desired_price<<",\"submitted_price\":"<<t.submitted_price<<",\"disposition\":\""<<disposition(t.disposition)<<"\",\"transaction_price\":"<<t.transaction_price<<",\"counterparty\":"<<t.counterparty<<"}";}std::cout<<"]";}
int main(){std::cout<<std::setprecision(12);const std::vector<analysis::NetworkEdge> full_edges{{0,1,.8},{1,2,.75}};const auto full=experiment::run_network_market(full_edges,0,10,2,424242,1800);const auto cut=experiment::run_network_market({{0,1,.8}},0,10,2,424242,1800);const auto null=experiment::run_network_market(full_edges,0,0,2,424242,1800);std::cout<<"{\"source\":\"CoAgentics v26 C++ full-market engine\",\"data_type\":\"controlled_simulation\",\"seed\":424242,\"events\":1800,\"traders\":12,\"protocol\":\"12-trader CDA, synthetic marginal schedules\",\"network\":{\"edges\":[{\"from\":0,\"to\":1,\"weight\":0.8},{\"from\":1,\"to\":2,\"weight\":0.75}],\"origin\":0,\"impulse\":10,\"steps\":2,\"exposure\":[";for(size_t i=0;i<full.exposure.responses.size();++i){if(i)std::cout<<",";std::cout<<full.exposure.responses[i];}std::cout<<"],\"shift\":[";for(size_t i=0;i<full.attempted_quote_shift.size();++i){if(i)std::cout<<",";std::cout<<full.attempted_quote_shift[i];}std::cout<<"],\"matched_attempts\":[";for(size_t i=0;i<full.matched_attempts.size();++i){if(i)std::cout<<",";std::cout<<full.matched_attempts[i];}std::cout<<"]},\"arms\":{\"control\":{";std::cout<<"\"outcome\":";outcome(full.market.outcomes.control);std::cout<<",\"trace\":";traces(full.market.control);std::cout<<"},\"treatment\":{\"outcome\":";outcome(full.market.outcomes.treatment);std::cout<<",\"trace\":";traces(full.market.treatment);std::cout<<"}},\"comparisons\":{\"edge_cut\":{\"outcome\":";outcome(cut.market.outcomes.treatment);std::cout<<",\"node2_shift\":"<<cut.attempted_quote_shift[2]<<"},\"null\":{\"outcome\":";outcome(null.market.outcomes.treatment);std::cout<<",\"node2_shift\":"<<null.attempted_quote_shift[2]<<"}}}";}
